def main() -> None:
    print(f"SAI2 Archipelago seed: {SEED}")
    print()

    rom = load_rom(INPUT_ROM)

    patched = 0

    for location_name, item_name in PLACEMENTS.items():

        location = location_table[location_name]
        item = item_table[item_name]

        if location.rom_address is None:
            raise ValueError(
                f"{location_name} has no ROM address."
            )

        if item.rom_id is None:
            raise ValueError(
                f"{item_name} has no ROM item ID."
            )

        patch_standard_location(
            rom,
            location.rom_address,
            item.rom_id,
        )

        print(
            f"PATCH: {location_name} -> {item_name} "
            f"(0x{item.rom_id:04X})"
        )

        patched += 1

    save_rom(
        rom,
        OUTPUT_ROM,
    )

    print()
    print("----------------------------------------")
    print(f"Standard chests patched: {patched}")
    print(f"ROM: {OUTPUT_ROM}")
    print("----------------------------------------")


if __name__ == "__main__":
    main()